package village.compiler

import org.objectweb.asm.ClassReader
import org.objectweb.asm.ClassVisitor
import org.objectweb.asm.MethodVisitor
import org.objectweb.asm.Opcodes

/**
 * The generated file compiled next to the player's file for every attempt (design D4). It holds a
 * reserved-name object implementing `village.api.LevelEntry` whose `content` calls the level's
 * entry composable, so the host never calls player functions reflectively. Because it is a
 * separate file, the player's line numbers need no remapping.
 *
 * Errors reported against this hidden file are translated into one CONTRACT diagnostic that names
 * the signature the level expects.
 */
internal class EntryWrapper(private val playerSource: String, private val entryFunction: String) {

    private val playerPackage: String? =
        Regex("""^\s*package\s+([\w.]+)""", RegexOption.MULTILINE).find(playerSource)?.groupValues?.get(1)

    /** `@Annotations modifiers fun Entry(`: group 1 = annotations, 2 = modifiers, 3 = the name. */
    private val declaration: MatchResult? =
        Regex("""((?:@[\w.]+(?:\([^)]*\))?\s+)*)((?:\w+\s+)*)fun\s+(${Regex.escape(entryFunction)})\s*\(""")
            .find(playerSource)

    private val expected = "@Composable fun $entryFunction()"

    val source: String = buildString {
        appendLine("// Generated by Compose Village for each attempt. Never shown to the player.")
        appendLine("object $CLASS_NAME : village.api.LevelEntry {")
        val call = if (playerPackage != null) "$playerPackage.$entryFunction" else entryFunction
        appendLine("    override val content: @androidx.compose.runtime.Composable () -> Unit = { $call() }")
        appendLine("}")
    }

    /**
     * Player-file diagnostics pass through unchanged; wrapper-file errors collapse into one CONTRACT
     * diagnostic. Messages without a location (line 0) pass through as-is.
     *
     * @param classes the compiled classes when compilation succeeded, used to check that the entry
     *   function really is `@Composable` (calling a plain function from the wrapper compiles fine).
     */
    fun mapDiagnostics(raw: List<RawDiagnostic>, classes: Map<String, ByteArray>): List<Diagnostic> {
        val result = mutableListOf<Diagnostic>()
        var wrapperError: RawDiagnostic? = null
        for (d in raw) {
            when (d.fileName) {
                FILE_NAME -> if (d.severity == Severity.ERROR && wrapperError == null) wrapperError = d
                else -> result += Diagnostic(d.severity, d.line, d.column, d.message, d.endLine, d.endColumn)
            }
        }
        val contract = when {
            wrapperError != null -> contractFor(wrapperError)
            !isComposable(classes) -> contract("`$entryFunction` must be annotated `@Composable`: the level shows it as UI. Expected `$expected`.")
            else -> null
        }
        return (listOfNotNull(contract) + result).sortedWith(compareBy({ it.line }, { it.column }))
    }

    private fun contractFor(error: RawDiagnostic): Diagnostic = when {
        declaration == null || error.message.contains("Unresolved reference") ->
            contract("This level needs a function `$expected`, but your file doesn't declare one.")
        error.message.contains("Cannot access") || "private" in declaration.groupValues[2].split(Regex("""\s+""")) ->
            contract("`$entryFunction` must not be private: the level needs to call it. Expected `$expected`.")
        else ->
            contract("The level calls `$entryFunction()` with no arguments. Expected `$expected`.")
    }

    /**
     * After a successful compile the bytecode decides: the Compose plugin gives every composable a
     * `Composer` parameter. After a failed compile there are no classes, so fall back to the source.
     */
    private fun isComposable(classes: Map<String, ByteArray>): Boolean {
        if (classes.isEmpty()) return declaration == null || declaration.groupValues[1].contains("Composable")
        val descriptors = mutableListOf<String>()
        for ((name, bytes) in classes) {
            if (name.contains(CLASS_NAME)) continue
            ClassReader(bytes).accept(object : ClassVisitor(Opcodes.ASM9) {
                override fun visitMethod(access: Int, name: String, descriptor: String, signature: String?, exceptions: Array<out String>?): MethodVisitor? {
                    if (name == entryFunction && access and Opcodes.ACC_STATIC != 0) descriptors += descriptor
                    return null
                }
            }, ClassReader.SKIP_CODE or ClassReader.SKIP_DEBUG or ClassReader.SKIP_FRAMES)
        }
        return descriptors.isEmpty() || descriptors.any { it.contains("Landroidx/compose/runtime/Composer;") }
    }

    /** Points at the entry declaration when there is one, otherwise at the top of the file. */
    private fun contract(message: String): Diagnostic {
        val (line, column) = declaration?.groups?.get(3)?.range?.first?.let { offset ->
            val before = playerSource.substring(0, offset)
            (before.count { it == '\n' } + 1) to (offset - before.lastIndexOf('\n'))
        } ?: (1 to 1)
        return Diagnostic(Severity.ERROR, line, column, message, source = Diagnostic.Source.CONTRACT)
    }

    companion object {
        /** Reserved name: the double underscore keeps it clear of anything a player would write. */
        const val CLASS_NAME = "__VillageEntry"
        const val FILE_NAME = "$CLASS_NAME.kt"
    }
}
